/// One typed key on a first-release Transform/Property curve.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TimelinePropertyKey {
    /// Tick relative to the containing clip start.
    pub tick: TimelineTick,
    /// Typed key value.
    pub value: TimelinePropertyValue,
}

/// Samples an explicitly typed Timeline property curve at `tick`.
///
/// Values clamp to the first/last key. Numbers and vectors interpolate linearly,
/// booleans use step sampling, and quaternions use normalized shortest-path lerp.
/// Invalid or mixed-type key sequences return `None` instead of fabricating a value.
pub fn sample_timeline_property(
    keys: &[TimelinePropertyKey],
    tick: TimelineTick,
) -> Option<TimelinePropertyValue> {
    let first = keys.first()?;
    if tick <= first.tick {
        return Some(first.value.clone());
    }
    let last = keys.last()?;
    if tick >= last.tick {
        return Some(last.value.clone());
    }

    for pair in keys.windows(2) {
        let left = &pair[0];
        let right = &pair[1];
        if tick >= right.tick {
            continue;
        }
        if left.value.kind() != right.value.kind() {
            return None;
        }
        let span = right.tick.get().saturating_sub(left.tick.get());
        if span <= 0 {
            return None;
        }
        let offset = tick.get().saturating_sub(left.tick.get());
        let alpha = offset as f64 / span as f64;
        return interpolate_property_value(&left.value, &right.value, alpha);
    }
    None
}

fn interpolate_property_value(
    left: &TimelinePropertyValue,
    right: &TimelinePropertyValue,
    alpha: f64,
) -> Option<TimelinePropertyValue> {
    let alpha = alpha.clamp(0.0, 1.0);
    match (left, right) {
        (TimelinePropertyValue::Bool(value), TimelinePropertyValue::Bool(_)) => {
            Some(TimelinePropertyValue::Bool(*value))
        }
        (TimelinePropertyValue::Number(left), TimelinePropertyValue::Number(right)) => {
            Some(TimelinePropertyValue::Number(left + (right - left) * alpha))
        }
        (TimelinePropertyValue::Vec3(left), TimelinePropertyValue::Vec3(right)) => {
            let mut value = [0.0; 3];
            for index in 0..3 {
                value[index] = left[index] + (right[index] - left[index]) * alpha;
            }
            Some(TimelinePropertyValue::Vec3(value))
        }
        (TimelinePropertyValue::Quat(left), TimelinePropertyValue::Quat(right)) => {
            let dot = left
                .iter()
                .zip(right.iter())
                .map(|(left, right)| left * right)
                .sum::<f64>();
            let sign = if dot < 0.0 { -1.0 } else { 1.0 };
            let mut value = [0.0; 4];
            for index in 0..4 {
                value[index] = left[index] * (1.0 - alpha) + right[index] * sign * alpha;
            }
            let length_squared = value.iter().map(|component| component * component).sum::<f64>();
            if !length_squared.is_finite() || length_squared <= f64::EPSILON {
                return None;
            }
            let inverse_length = length_squared.sqrt().recip();
            for component in &mut value {
                *component *= inverse_length;
            }
            Some(TimelinePropertyValue::Quat(value))
        }
        _ => None,
    }
}

